#include <iostream>

int main() {
    double number1 = 0.0;
    double number2 = 0.0;
    double number3 = 0.0;

    std::cout << "Enter three numbers: ";
    if (std::cin >> number1 >> number2 >> number3) {
        double average = (number1 + number2 + number3) / 3.0;
        std::cout << "The average of " << number1 << " " << number2
                  << " " << number3 << " is " << average << std::endl;
    }
    return 0;
}

#include <iostream>

int main() {
    double radius = 1.0;
    double area = radius * radius * 3.14159;
    std::cout << "The area is " << area << " for radius " << radius << std::endl;

    radius = 2.0;
    area = radius * radius * 3.14159;
    std::cout << "The area is " << area << " for radius " << radius << std::endl;

    return 0;
}
